select public.trials_seed($trial${"slug": "crown", "acronym": "CROWN", "title": "Lorlatinib vs crizotinib, CBNPC avancé ALK positif", "diagnosis": "CBNPC", "markers": "ALK", "lines": ["1L"], "drugs": "lorlatinib", "phase": "Phase III, ouvert", "design": {"population": "CBNPC avancé ALK positif sans traitement systémique préalable", "randomization": "1:1", "arms": [{"name": "Lorlatinib 100 mg/j", "n": 149}, {"name": "Crizotinib 250 mg 2x/j", "n": 147}], "primary": "PFS (revue centrale indépendante)"}, "outcomes": [{"ep": "PFS", "label": "Survie sans progression", "timepoint": "5 ans (investigateur, post hoc)", "hr": 0.19, "lo": 0.13, "hi": 0.27, "arms": [{"arm": "Lorlatinib", "nr": true, "rate": 60}, {"arm": "Crizotinib", "median": 9.1, "rate": 8}], "note": "Taux : sans progression à 5 ans"}, {"ep": "PFS", "label": "Délai jusqu'à progression intracrânienne", "timepoint": "5 ans", "hr": 0.06, "lo": 0.03, "hi": 0.12, "arms": []}, {"ep": "ORR", "label": "Taux de réponse objective", "timepoint": "analyse primaire", "arms": [{"arm": "Lorlatinib", "rate": 76}, {"arm": "Crizotinib", "rate": 58}]}, {"ep": "ORR", "label": "Réponse intracrânienne (métastases mesurables)", "timepoint": "analyse primaire", "arms": [{"arm": "Lorlatinib", "rate": 82}, {"arm": "Crizotinib", "rate": 23}]}], "safety": "Grade 3-4 : 72 % vs 56 %, surtout troubles lipidiques ; effets cognitifs et thymiques à surveiller.", "summary": "Le lorlatinib procure la survie sans progression la plus longue rapportée pour une thérapie ciblée dans le CBNPC : médiane non atteinte à 5 ans, avec une protection cérébrale remarquable.", "strengths": "PFS à 5 ans de 60 % ; efficacité intracrânienne majeure ; absence de nouvelles mutations de résistance ALK détectées.", "limitations": "Comparateur crizotinib (pas d'alectinib ni de brigatinib) ; données à 5 ans post hoc ; effets neuropsychiques et métaboliques.", "practice": "oui", "practice_text": "Option de choix en première ligne du CBNPC ALK positif, notamment avec atteinte cérébrale.", "refs": [{"label": "Shaw AT et al. First-Line Lorlatinib or Crizotinib in Advanced ALK-Positive Lung Cancer", "pmid": "33207094", "doi": "10.1056/NEJMoa2027187", "journal": "N Engl J Med", "year": 2020}, {"label": "Solomon BJ et al. 5-Year Outcomes From the Phase III CROWN Study", "pmid": "38819031", "doi": "10.1200/JCO.24.00581", "journal": "J Clin Oncol", "year": 2024}], "clinic": "Thoracique"}$trial$::jsonb);
select public.trials_seed($trial${"slug": "alta-1l", "acronym": "ALTA-1L", "title": "Brigatinib vs crizotinib, CBNPC avancé ALK positif", "diagnosis": "CBNPC", "markers": "ALK", "lines": ["1L"], "drugs": "brigatinib", "phase": "Phase III, ouvert", "design": {"population": "CBNPC avancé ALK positif sans inhibiteur d'ALK préalable", "randomization": "1:1", "arms": [{"name": "Brigatinib 180 mg/j (introduction 90 mg 7 jours)", "n": 137}, {"name": "Crizotinib 250 mg 2x/j", "n": 138}], "primary": "PFS (revue centrale indépendante)"}, "outcomes": [{"ep": "PFS", "label": "Survie sans progression", "timepoint": "première analyse intermédiaire", "hr": 0.49, "lo": 0.33, "hi": 0.74, "p": "<0,001", "arms": [{"arm": "Brigatinib", "rate": 67}, {"arm": "Crizotinib", "rate": 43}], "note": "Taux : sans progression à 12 mois"}, {"ep": "ORR", "label": "Taux de réponse objective confirmée", "arms": [{"arm": "Brigatinib", "rate": 71}, {"arm": "Crizotinib", "rate": 60}]}, {"ep": "ORR", "label": "Réponse intracrânienne (lésions mesurables)", "arms": [{"arm": "Brigatinib", "rate": 78}, {"arm": "Crizotinib", "rate": 29}]}], "safety": "Pas de nouveau signal ; surveiller les événements pulmonaires précoces (d'où la phase d'introduction à 90 mg).", "summary": "Le brigatinib améliore la survie sans progression et l'activité cérébrale par rapport au crizotinib en première ligne ALK.", "strengths": "Revue centrale indépendante ; forte activité intracrânienne.", "limitations": "Analyse intermédiaire précoce (mise à jour finale à intégrer) ; comparateur crizotinib ; essai ouvert.", "practice": "oui", "practice_text": "Une des options de première ligne ALK, aux côtés de l'alectinib et du lorlatinib.", "refs": [{"label": "Camidge DR et al. Brigatinib versus Crizotinib in ALK-Positive NSCLC", "pmid": "30280657", "doi": "10.1056/NEJMoa1810171", "journal": "N Engl J Med", "year": 2018}], "clinic": "Thoracique"}$trial$::jsonb);
select public.trials_seed($trial${"slug": "libretto-001", "acronym": "LIBRETTO-001", "title": "Selpercatinib dans le CBNPC avec fusion RET", "diagnosis": "CBNPC", "markers": "RET", "lines": ["1L", "2L", "3L"], "drugs": "selpercatinib", "phase": "Phase I-II, un seul bras", "design": {"population": "CBNPC avancé avec fusion RET, prétraité par platine ou non traité (cohortes distinctes)", "randomization": "aucune", "arms": [{"name": "Prétraités par platine", "n": 105}, {"name": "Non traités", "n": 39}], "primary": "Taux de réponse objective (comité indépendant)"}, "outcomes": [{"ep": "ORR", "label": "Taux de réponse objective", "arms": [{"arm": "Prétraités par platine", "rate": 64}, {"arm": "Non traités", "rate": 85}]}, {"ep": "ORR", "label": "Réponse intracrânienne (métastases mesurables, n = 11)", "arms": [{"arm": "Tous", "rate": 91}]}, {"ep": "DoR", "label": "Durée de réponse médiane (prétraités)", "arms": [{"arm": "Prétraités par platine", "median": 17.5}]}], "safety": "Grade ≥ 3 les plus fréquents : hypertension 14 %, ALAT 12 %, ASAT 10 % ; arrêts pour toxicité 2 %.", "summary": "Le selpercatinib induit des réponses fréquentes et durables, y compris cérébrales, dans le CBNPC avec fusion RET.", "strengths": "Taux de réponse élevés et durables ; activité intracrânienne ; tolérance favorable.", "limitations": "Essai sans bras contrôle ; effectifs limités dans la cohorte non traitée ; critère de substitution (réponse).", "practice": "oui", "practice_text": "A établi le ciblage de RET ; standard après test moléculaire positif.", "refs": [{"label": "Drilon A et al. Efficacy of Selpercatinib in RET Fusion-Positive NSCLC", "pmid": "32846060", "doi": "10.1056/NEJMoa2005653", "journal": "N Engl J Med", "year": 2020}], "clinic": "Thoracique"}$trial$::jsonb);
