select public.trials_seed($trial${"slug": "destiny-lung02", "acronym": "DESTINY-Lung02", "title": "Trastuzumab deruxtecan 5,4 vs 6,4 mg/kg, CBNPC métastatique HER2 muté prétraité", "diagnosis": "CBNPC", "markers": "HER2 (ERBB2) muté", "lines": ["2L", "3L"], "drugs": "trastuzumab deruxtecan", "phase": "Phase II randomisée (deux doses), aveugle", "design": {"population": "CBNPC métastatique HER2 muté (mutations ponctuelles et insertions de l'exon 20) prétraité par platine", "randomization": "2:1", "total": 152, "arms": [{"name": "T-DXd 5,4 mg/kg/3 sem.", "n": null}, {"name": "T-DXd 6,4 mg/kg/3 sem.", "n": null}], "primary": "Réponse objective confirmée (revue centrale indépendante)"}, "outcomes": [{"ep": "ORR", "label": "Taux de réponse objective confirmée", "arms": [{"arm": "5,4 mg/kg", "rate": 49.0}, {"arm": "6,4 mg/kg", "rate": 56.0}]}, {"ep": "DoR", "label": "Durée de réponse médiane", "arms": [{"arm": "5,4 mg/kg", "median": 16.8}, {"arm": "6,4 mg/kg", "nr": true}]}], "safety": "Effets liés de grade ≥ 3 : 38,6 % vs 58,0 % ; pneumopathies interstitielles liées : 12,9 % vs 28,0 %.", "summary": "Le trastuzumab deruxtecan à 5,4 mg/kg obtient environ 50 % de réponses dans le CBNPC HER2 muté prétraité, avec un meilleur profil de tolérance qu'à 6,4 mg/kg.", "strengths": "Comparaison randomisée de deux doses ; revue centrale ; réponses durables.", "limitations": "Pas de bras contrôle ; risque de pneumopathie interstitielle à surveiller étroitement.", "practice": "oui", "practice_text": "A fixé la dose de 5,4 mg/kg dans le CBNPC HER2 muté prétraité (hors limitation LS en Suisse : art. 71a OAMal).", "refs": [{"label": "Goto K et al. DESTINY-Lung02", "pmid": "37694347", "doi": "10.1200/JCO.23.01361", "journal": "J Clin Oncol", "year": 2023}], "clinic": "Thoracique"}$trial$::jsonb);
